use hp_pcf::{dmx::Value,editor::{Category,Document}};
use hp_gma::{AddonJson,GmaWriter,GmaSource};
fn a(v:Vec<(&str,Value)>)->Vec<(String,Value)>{v.into_iter().map(|(k,v)|(k.into(),v)).collect()}
fn leaf(d:&mut Document,name:&str,pos:[f32;3],count:i32)->Result<usize,Box<dyn std::error::Error>>{let id=d.create_system(name)?;d.set_attrs(id,a(vec![("max_particles",Value::Int(count)),("radius",Value::Float(4.)),("material",Value::Str("hp_capacity117/white".into())),("bounding_box_min",Value::Vec3([0.;3])),("bounding_box_max",Value::Vec3([0.;3]))]))?;d.add_operator_with_params(id,Category::Emitters,"emit_instantaneously",a(vec![("num_to_emit",Value::Int(count))]))?;d.add_operator_with_params(id,Category::Initializers,"Position Within Box Random",a(vec![("min",Value::Vec3(pos)),("max",Value::Vec3(pos))]))?;d.add_operator_with_params(id,Category::Initializers,"Lifetime Random",a(vec![("lifetime_min",Value::Float(100.)),("lifetime_max",Value::Float(100.))]))?;d.add_operator(id,Category::Renderers,"render_animated_sprites")?;Ok(id)}
fn main()->Result<(),Box<dyn std::error::Error>>{let out=std::env::args_os().nth(1).ok_or("output folder")?;let out=std::path::Path::new(&out);let mut d=Document::new();
let root=leaf(&mut d,"hp_capacity117_children",[-80.,0.,0.],1)?;
for i in 0..20{let child=leaf(&mut d,&format!("hp_capacity117_child{i}"),[-64.+32.*(i%5)as f32,0.,(i/5)as f32*32.],1)?;d.add_child(root,child,0.)?;}
let deep=leaf(&mut d,"hp_capacity117_deep",[-80.,0.,0.],1)?;let mut parent=deep;
for i in 0..6{let child=if i==5{leaf(&mut d,"hp_capacity117_terminal",[80.,0.,96.],1)?}else{d.create_system(&format!("hp_capacity117_depth{i}"))?};d.add_child(parent,child,0.)?;parent=child;}
for n in [6000,10000]{let id=leaf(&mut d,&format!("hp_capacity117_count{n}"),[0.;3],n)?;d.add_operator_with_params(id,Category::Initializers,"Remap Particle Count to Scalar",a(vec![("input minimum",Value::Int(0)),("input maximum",Value::Int(n-1)),("output field",Value::Int(7)),("output minimum",Value::Float(0.)),("output maximum",Value::Float(1.))]))?;d.add_operator_with_params(id,Category::Initializers,"Remap Scalar to Vector",a(vec![("input field",Value::Int(7)),("input minimum",Value::Float(0.)),("input maximum",Value::Float(1.)),("output field",Value::Int(0)),("output minimum",Value::Vec3([0.;3])),("output maximum",Value::Vec3([(n-1)as f32,0.,0.]))]))?;}
std::fs::write(out.join("hp_capacity117.pcf"),d.to_bytes()?)?;
let mut g=GmaWriter::new(AddonJson{title:"Owned particle hierarchy and count parity".into(),..Default::default()});g.add("materials/hp_capacity117/white.vmt",GmaSource::Bytes(br#"UnlitGeneric { "$basetexture" "hp_capacity117/white" "$vertexcolor" "1" "$vertexalpha" "1" }"#.to_vec())).unwrap();g.add("materials/hp_capacity117/white.vtf",GmaSource::Bytes(hp_gma::GmaArchive::open(out.join("hp_capacity117.gma"))?.read("materials/hp_capacity117/white.vtf")?.ok_or("owned white texture")?)).unwrap();g.write(&out.join("hp_capacity117.gma"))?;Ok(())}
